// Kara şimşek: ışık 6 LED'de sağa, sonra sola kayar.
const int LEDLER[] = {7, 6, 5, 4, 3, 2};  // soldan sağa LED pinleri
const int ADET = 6;                       // LED sayısı
const int BEKLE_MS = 100;                 // bir LED'in yanık kaldığı süre

// i. LED'i kısa bir süre yakar, sonra söndürür.
void yak(int i) {
  digitalWrite(LEDLER[i], HIGH);
  delay(BEKLE_MS);
  digitalWrite(LEDLER[i], LOW);
}

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < ADET; i++) {
    pinMode(LEDLER[i], OUTPUT);
  }
}

void loop() {
  Serial.println("Saga");
  for (int i = 0; i < ADET; i++) {      // soldan sağa
    yak(i);
  }
  Serial.println("Sola");
  for (int i = ADET - 2; i > 0; i--) {  // sağdan sola; uçları iki kez yakma
    yak(i);
  }
}
